<?php
namespace App\Models\Documents;
use Illuminate\Database\Eloquent\Model;
class PostedShipment extends Model { protected $table='posted_shipments'; protected $guarded=[]; protected $casts=['document_date'=>'date','posted_at'=>'datetime','subtotal'=>'decimal:4','discount_total'=>'decimal:4','tax_total'=>'decimal:4','grand_total'=>'decimal:4']; public function lines(){return $this->hasMany(PostedShipmentLine::class,'posted_shipment_id');} public function customer(){return $this->belongsTo(\App\Models\Customer::class,'customer_id');} public function location(){return $this->belongsTo(\App\Models\Location::class,'location_id');} public function bin(){return $this->belongsTo(\App\Models\LocationBin::class,'bin_id');} public function source(){return $this->belongsTo(Shipment::class,'source_shipment_id');} public function glBatch(){return $this->belongsTo(\App\Models\GlBatch::class);} public function undo(){return $this->hasOne(PostedDocumentUndo::class,'posted_id')->where('posted_type','PostedShipment');} public function effectiveStatus(): string { return $this->undo()->exists()?'UNDO':'POSTED'; } }
